namespace sv_bb451f718eda445fbdab2252c1482e73.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_bb451f718eda445fbdab2252c1482e73.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
            </div>
        }
    </main>
</div>

@* ===== PROFILE SECTION ===== *@
@code {
    private RenderFragment ProfileSection => __builder =>
    {
        <section class="settings-section">
            <h2>Profile Settings</h2>

            <div class="avatar-preview">
                <img src="@editProfile!.AvatarUrl" alt="Avatar" class="avatar-img" />
                <p class="avatar-url">@editProfile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ===== NOTIFICATIONS SECTION ===== *@
@code {
    private RenderFragment NotificationsSection => __builder =>
    {
        <section class="settings-section">
            <h2>Notification Preferences</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications!.EmailNotifications" />
                    <span class="toggle-switch"></span>
                    Email Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.PushNotifications" />
                    <span class="toggle-switch"></span>
                    Push Notifications
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                    <span class="toggle-switch"></span>
                    Weekly Digest
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in availableChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@editNotifications.MutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                        @ch
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* ===== SECURITY SECTION ===== *@
@code {
    private RenderFragment SecuritySection => __builder =>
    {
        <section class="settings-section">
            <h2>Security Settings</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => showChangePassword = !showChangePassword">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showChangePassword ? "▼" : "▶")</span>
                </button>
                @if (showChangePassword)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group tfa-group">
                <label class="toggle-label">
                    <input type="checkbox" checked="@securitySettings!.TwoFactorEnabled" disabled />
                    <span class="toggle-switch"></span>
                    Two-Factor Authentication
                </label>
                <span class="status-indicator @(securitySettings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(securitySettings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>

            @if (securitySettings.LastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in securitySettings.Sessions)
                    {
                        var s = session;
                        <tr>
                            <td>@s.Device</td>
                            <td>@s.Location</td>
                            <td>@s.LastActive.ToString("g")</td>
                            <td>
                                @if (s.Id != currentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(s.Id, s.Device)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal-dialog" @onclick:stopPropagation="true">
                        <h3>Confirm Session Revocation</h3>
                        <p>Are you sure you want to revoke the session on <strong>@revokeDeviceName</strong>?</p>
                        <div class="button-group">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ===== APPEARANCE SECTION ===== *@
@code {
    private RenderFragment AppearanceSection => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance Settings</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light"
                               checked="@(editAppearance!.Theme == "Light")"
                               @onchange='() => editAppearance.Theme = "Light"' /> Light
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark"
                               checked="@(editAppearance.Theme == "Dark")"
                               @onchange='() => editAppearance.Theme = "Dark"' /> Dark
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System"
                               checked="@(editAppearance.Theme == "System")"
                               @onchange='() => editAppearance.Theme = "System"' /> System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small"
                               checked="@(editAppearance.FontSize == "Small")"
                               @onchange='() => editAppearance.FontSize = "Small"' /> Small
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium"
                               checked="@(editAppearance.FontSize == "Medium")"
                               @onchange='() => editAppearance.FontSize = "Medium"' /> Medium
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large"
                               checked="@(editAppearance.FontSize == "Large")"
                               @onchange='() => editAppearance.FontSize = "Large"' /> Large
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="editAppearance.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                    <span class="toggle-switch"></span>
                    Compact Mode
                </label>
            </div>

            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <button class="btn btn-primary">Sample Button</button>
                <p class="preview-meta">Theme: @editAppearance.Theme | Font: @editAppearance.FontSize | Compact: @editAppearance.CompactMode</p>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "";

    // Profile state
    private EditableProfile? editProfile;
    private UserProfile? savedProfile;

    // Notifications state
    private EditableNotifications? editNotifications;
    private List<string> availableChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool showChangePassword;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string currentSessionId = "";
    private bool showRevokeConfirmation;
    private string? revokeSessionId;
    private string? revokeDeviceName;

    // Appearance state
    private EditableAppearance? editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        isLoading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        savedProfile = await profileTask;
        editProfile = new EditableProfile(savedProfile);

        var notifPrefs = await notifTask;
        editNotifications = new EditableNotifications(notifPrefs);

        securitySettings = await securityTask;
        if (securitySettings.Sessions.Count > 0)
            currentSessionId = securitySettings.Sessions[0].Id;

        var appearance = await appearanceTask;
        editAppearance = new EditableAppearance(appearance);
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile!.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        editProfile = new EditableProfile(savedProfile!);
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications!.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications!.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications!.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showChangePassword = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(string sessionId, string device)
    {
        revokeSessionId = sessionId;
        revokeDeviceName = device;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        await SettingsService.RevokeSessionAsync(revokeSessionId!);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        showRevokeConfirmation = false;
        ShowToast("Session revoked.", "success");
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = new List<string> { "preview" };
        if (editAppearance!.Theme == "Dark") classes.Add("preview-dark");
        else if (editAppearance.Theme == "Light") classes.Add("preview-light");
        if (editAppearance.FontSize == "Small") classes.Add("preview-font-small");
        else if (editAppearance.FontSize == "Large") classes.Add("preview-font-large");
        if (editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editAppearance!.Theme, editAppearance.FontSize, editAppearance.Language, editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private CancellationTokenSource? _toastCts;

    private async void ShowToast(string message, string type)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;

        toastMessage = message;
        toastType = type;
        StateHasChanged();

        try
        {
            await Task.Delay(3000, token);
            toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    // Editable model classes
    private class EditableProfile
    {
        public string DisplayName { get; set; }
        public string Email { get; set; }
        public string AvatarUrl { get; set; }
        public string Bio { get; set; }

        public EditableProfile(UserProfile profile)
        {
            DisplayName = profile.DisplayName;
            Email = profile.Email;
            AvatarUrl = profile.AvatarUrl;
            Bio = profile.Bio;
        }
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; }

        public EditableNotifications(NotificationPrefs prefs)
        {
            EmailNotifications = prefs.EmailNotifications;
            PushNotifications = prefs.PushNotifications;
            WeeklyDigest = prefs.WeeklyDigest;
            MutedChannels = new List<string>(prefs.MutedChannels);
        }
    }

    private class EditableAppearance
    {
        public string Theme { get; set; }
        public string FontSize { get; set; }
        public string Language { get; set; }
        public bool CompactMode { get; set; }

        public EditableAppearance(AppearanceSettings settings)
        {
            Theme = settings.Theme;
            FontSize = settings.FontSize;
            Language = settings.Language;
            CompactMode = settings.CompactMode;
        }
    }
}

