+    // Notifications state
+    private EditableNotifications? editNotifications;
+    private List<string> availableChannels = new() { "general", "announcements", "random", "engineering", "design", "marketing" };
+
+    // Security state
+    private SecuritySettings? securitySettings;
+    private bool showChangePassword;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
